import os, glob, json, re
def biggest_content(jf):
    mx=0
    err=None
    exitr=None
    nlines=0
    try:
        for line in open(jf,errors="ignore"):
            nlines+=1
            try: d=json.loads(line)
            except: continue
            s=json.dumps(d)
            # find error markers
            low=s.lower()
            if err is None:
                for k in ("badrequest","maximum context","context length","reduce the length","exit_reason","400"):
                    if k in low:
                        m=re.search(r".{0,20}(badrequest|maximum context|context length|reduce the length).{0,80}", s, re.I)
                        if m: err=m.group(0)
            if '"exit_reason"' in s or '"error"' in s:
                m=re.search(r'"exit_reason"\s*:\s*"([^"]*)"', s)
                if m: exitr=m.group(1)
            # biggest string
            def walk(o):
                nonlocal mx
                if isinstance(o,str):
                    if len(o)>mx: mx=len(o)
                elif isinstance(o,dict):
                    for v in o.values(): walk(v)
                elif isinstance(o,list):
                    for v in o: walk(v)
            walk(d)
    except Exception as e:
        return None
    return (nlines,mx,exitr,err)

for d in sorted(glob.glob("*__*/")):
