tasks=["overfull-hbox","protein-assembly","sam-cell-seg","configure-git-webserver","large-scale-text-editing","llm-inference-batching-scheduler","adaptive-rejection-sampler"]
def scan(tr):
    best=[0,None,None,None]
    for i,line in enumerate(open(tr,errors="ignore")):
        try: d2=json.loads(line)
        except: continue
        typ=d2.get("type")
        stack=[(d2,"")]
        while stack:
            o,path=stack.pop()
            if isinstance(o,str):
                if len(o)>best[0]: best=[len(o),typ,path,i]
            elif isinstance(o,dict):
                for k,v in o.items(): stack.append((v,path+"/"+str(k)))
            elif isinstance(o,list):
                for j,v in enumerate(o): stack.append((v,path+f"[{j}]"))
    return best
for tk in tasks:
    d=glob.glob(tk+"__*/")[0]
    tr=[t for t in glob.glob(os.path.join(d,"agent","oh_runs","*","*.jsonl")) if not t.endswith("_trace.jsonl")][0]
    b=scan(tr)
    print(f"{tk:36s} len={b[0]:8d} type={str(b[1]):16s} path={b[2][:44]}")
